import java.util.*;

class Solution {
    static int insertPosition(int[] times, int newTime) {
        int low = 0, high = times.length;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (times[mid] < newTime) low = mid + 1;
            else high = mid;
        }
        return low;
    }
}
